INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('ng-mau-500-coffin', 'MAU-500 Medical Automation Unit ("the Coffin")', 'rifts', 'drone', 'None: an automated unit that treats one patient at a time.', 'One patient, human-sized and up to 7 ft (2.1 m) tall, lying inside.', 'None; it has to be carried by some other vehicle or means.', NULL, NULL, 'Height/depth 4 ft (1.2 m); width 3 ft (0.9 m); length 8 ft (2.4 m)', '380 lbs (171 kg)', 75, 1, NULL, 5400000, '5.4 million credits with every feature, the first load of medical nanobots and medicine included. Wiring it into an existing vehicle''s, trailer''s or clinic''s Solid Oxide or nuclear supply is 300,000 more.', 'Also sold as the Med-Box; the nickname comes from its shape. A portable robot medical unit from a team under Dale Gifford, James L. Giltz and Robert Dugan, built to handle cuts, gunshot wounds, shrapnel, fractures and bruising in the field so that Body Fixers can attend to the gravely hurt; it is not meant to replace them. The page dates its release to the winter of 208 P.A., likely a misprint for 108. It fits in most vans, a pickup bed or anything bigger, and mobile hospitals and field units usually carry two or more; some medics bolt one into the bed of a cargo drone or light truck. Use: the patient lies inside, the lid closes, and a full body scan begins under warm light with calming music and a gentle female voice explaining each step. Folding robot arms (the biggest in the lid), nanobots, syringes and other tools then clean wounds, pull shrapnel, do minor surgery and give medicine; when it is done the lid opens and the voice explains the condition and any follow-up care. A fold-out screen shows a kindly animated face, or a real doctor''s through an outside camera and microphone, and can show diagrams to the patient. Scanners: weight, breathing, pulse, blood pressure, blood loss, temperature, dehydration, stress, sweat and the like, plus blood analysis, EKG, EEG, MRI, ultrasound and CAT scan in minutes. Nanobot load (one field kit''s worth, enough for most patients; reusable 1D6+6 times after being cleaned and recharged inside): 24 IRMSS, 6 IRVT, 24 RAU, 48 RMK, 12 RSU and 12 Bio-Braces (see Rifts Ultimate Edition p.263; the Bio-Brace is later in this book). Diagnosis: 91% humans, 56% D-Bees; useless on supernatural beings and creatures of magic past obvious surface wounds. The first scan takes 15 seconds; a failed roll may be retried at 1D4+2 melee rounds, and a second failure leaves it treating only the obvious. Results go to medics outside in writing, speech, graphs and images on the outer monitor, or to a helmet HUD or a vehicle''s or base''s computers. Treatment: 88% humans, 50% D-Bees; success heals 2D6 Hit Points and stops further loss, failure leaves the patient no worse. Coma/death saves get the Professional Medical Treatment bonus. Life support: oxygen, breathing tube, transfusion and drugs to keep a patient alive in transit. Surgery: simple 98% humans/94% D-Bees; serious and internal 88%/56%; very complex 1D4x10%, needing a full team. It cannot do major heart or brain surgery, transplants or cyber-surgery. A successful operation heals 1D6 Hit Points and stabilizes; a failure leaves the patient no worse but untreated. Power: none of its own; it runs off an outside generator or Solid Oxide or nuclear supply, or six E-Clips in its housing, which last for 1D4+2 patients. Units built into vehicles, robots, clinics or hospitals draw on their host''s supply indefinitely.', 'Rifts World Book 34: Northern Gun Two p.235-236'),
  ('ng-robot-floater-camera', 'Robot Floater Camera', 'rifts', 'drone', 'None: a remote hovering camera.', 'None.', NULL, 'Hovers and drifts in any direction at up to 10 mph (16 km); ceiling 11 ft (3.4 m).', NULL, 'Height 9 in (23 cm); width 6 in (15 cm); length 18 in (46 cm)', '7 lbs (3.2 kg)', 18, 1, NULL, 35000, '35,000 credits.', 'Nicknamed Spy Cam, the Police Eye or simply Floater. A lunchbox-sized hovering robot camera made for the Enforcer Guardsman power armor and also sold to police forces. It scouts ahead, records arrests, interrogations and evidence, or holds back to film a fight; in the dark a passive light amplification Stealth Mode lets it see and record. Its feed goes wirelessly to the helmet HUDs of up to six Enforcer Guardsmen in real time, and it links to one Guardsman''s Criminal I.D. Recognition System. It carries a steerable flashlight (200 ft/61 m) and a laser distancer that measures range and paints targets (600 ft/183 m). Slow and low-flying, it is used in careful, slow-moving work, not high-speed chases. Criminal I.D. Recognition System: new and experimental for NG, about 89% reliable, tied to the armor''s cameras, gun camera and the Floater; it can match up to 250,000 faces of criminals, terrorists, wanted fugitives, Black Marketeers, bounty targets and enemies of the state, and also tattoos, scars, gang colors, patches and emblems, and can be loaded with anyone else who has been photographed. Bonus: +1 dodge against attacks and falling debris. Physical Strength: none. Cargo: none. Power: battery, 120 hours.', 'Rifts World Book 34: Northern Gun Two p.236-237'),
  ('ng-dx202-cargo-walker', 'DX-202 Cargo Walker', 'rifts', 'robot', 'One pilot in an open cage, or none when run by remote control.', 'A guard, supervisor, mechanic or rider may sit in the cage under remote control; up to four more can ride on top, against safety rules.', 'Runs at up to 45 mph (72 km) without tiring; half that or less under heavy cargo, and terrain may slow it. Cannot leap.', 'Cannot fly.', 'Wades water and snow up to 10 ft (3 m) and mud up to 5 ft (1.5 m) deep. Not submersible: it sinks, and its electronics fail 1D6+5 minutes under water, with the pilot exposed.', 'Height 15 ft (4.6 m); width 8 ft (2.4 m); length 18 ft (5.5 m) with the forklift arms extended, 10 ft (3 m) folded', '7.5 tons', 200, 1, NULL, 4200000, '4.2 million credits Solid Oxide, 5 million nuclear (10 year life). Buyers of four or more often get 15-20% off.', 'Model DX-202, classed as a Non-Combat Support Unit and Cargo Hauler, from a design team under David Klett, Stephen McDonald, Scott Norman and Alan Westchorl. A giant walking forklift seen on the Ishpeming docks, on freighters and in warehouses, building sites and factories, and on battlefields salvaging robots, vehicles and scrap, digging trenches and moving supplies. Each arm ends in a pair of forks lifting 10 tons, or 50 tons with both on one load; two walkers lift 100 tons or carry 80 together. The hydraulic fork housings extend to twice their reach, and each forearm has a small extending clamp hand (reach 4 ft/1.2 m, Robot P.S. 30) for crates and parts. A swappable back module takes a backhoe, steam shovel or crane; the crane pulls up to 12 tons (two walkers 30, four 60), and it rarely hauls and carries at once unless one load is under 8 tons. Armies and mercs use it to load missiles, ordnance and big guns onto robots and vehicles. One of NG''s best sellers, it can be driven or worked as a remote drone: cameras sit two per shoulder, two per forklift, two at the rear, one on the swivelling top mount with the spotlight, and one each front and back of the rearview mirror. Remote range is 2 miles (3.2 km) recommended, up to 5 miles (8 km) in open country, 2 miles (3.2 km) at most where there is interference; a rider who can pilot ground robots and has the override code can take control. Though unarmed, it is a favourite of small towns, new merc outfits and adventurers to rebuild: the open cage can be walled in with 60-120 M.D.C. of armour (still no life support), the forks swapped for heavy guns, giant blades, drills or chainsaws, and launchers bolted to the back, sides or top; NG sells a Combat Kit for the job. Robot P.S.: forklift arms 50, utility arms 30, cage mini-arms 9. Cargo: a small space for a pistol, lunchbox, canteen and a few E-Clips; more can be tied to the cage if it does not block sight or movement. Sensors: none to speak of; non-environmental, a basic radio, wireless computer feeds and navigation cameras. The top spotlight (1,000 ft/305 m) and dashboard-style camera (2,000 ft/610 m) swivel 360 degrees and tilt 45 up and down. Attacks: one per melee plus the pilot''s, or four in all under remote control. Power: Solid Oxide or nuclear (10 year life).', 'Rifts World Book 34: Northern Gun Two p.237-238'),
  ('ng-dx204-grub', 'DX-204 GRUB (General Robotic Ultra-Builder)', 'rifts', 'robot', 'One pilot in a side-facing cage, or none when run by remote control.', 'A guard, supervisor, mechanic or rider may sit in the cage under remote control.', 'Runs at up to 40 mph (64 km) without tiring; half that or less under heavy loads, and terrain may slow it. Cannot leap.', 'Cannot fly.', 'Wades water and snow up to 10 ft (3 m) and mud up to 5 ft (1.5 m) deep. Not submersible: it sinks, and its electronics fail 1D6+5 minutes under water, with the pilot exposed.', 'Height 20 ft (6.1 m) with the crane stowed; width 16 ft (4.9 m); length 18 ft (5.5 m). Main arms reach 15 ft (4.6 m), utility arms 12 ft (3.7 m)', '20 tons', 300, 1, NULL, 7400000, '7.4 million credits Solid Oxide, 8 million nuclear (10 year life). Buyers of four or more often get 15-20% off.', 'Model DX-204 (the stat block prints DX-202), classed as a Non-Combat Labor/Construction and Support Unit. A boxy, ungainly construction robot whose square legs put out stabilizers when it lifts heavy loads. Its torso holds a side-facing pilot''s cage of M.D.C. plexiglass among the machinery. A top turret crane turns 360 degrees, rises 6 ft (1.8 m) and reaches out 8 ft (2.4 m), hoisting and pulling up to 20 tons. A huge back-mounted multi-tool grips like pliers, holds pipe and parts (10 tons), shears, saws, or puts out a welding torch. Winches front and back each pull 30 tons. Two small clamp-handed shoulder arms (Robot P.S. 30, 2 tons) fold out to hold work and carry supplies; they turn to face front, side or back. The big arms lift 15 tons each or 30 together, yet are fine enough to hold a worker up to a high scaffold like a cherry-picker; the hands turn 360 degrees, extend 4 ft (1.2 m) from the wrist, and dig, clear rubble, punch through walls and tear down or raise facades. Each palm carries eight small lasers for cutting and welding. Used in building, excavation, firefighting and hauling. It cannot easily be turned into a war machine. Like the Cargo Walker it can be driven or run as a remote drone, with cameras two per shoulder, two per hand, two at the rear, one on the crane, two on the multi-tool, one on the ball light and one each front and back of the cage. Remote range: the description says about 2 miles (3.2 km), up to 5 (8 km); the stat block says up to 50 miles (80 km), 30 (48 km) or less recommended, as little as 10 (16 km) with interference. Robot P.S.: main arms and hands 50, utility arms 30. Cargo: a small space for a pistol, lunchbox, canteen and a few E-Clips; more can be tied to the cage if it does not block sight or movement. Sensors: none to speak of; non-environmental, basic radio and navigation cameras. Ball spotlight (1,200 ft/366 m, wide or narrow beam) and camera (2,000 ft/610 m, 8x telescopic and 12x macro) in a front ball turret that turns 360 degrees and tilts 90 up and down. Ankle spotlights angle up 70 degrees. Attacks: one per melee plus the pilot''s, or four in all under remote control. NG''s Drone Control and Command Gauntlet (described under Fido) can run it. Power: Solid Oxide or nuclear (10 year life).', 'Rifts World Book 34: Northern Gun Two p.240-241'),
  ('ng-brv10-vulture', 'BRV-10 Vulture Battlefield Recovery Vehicle', 'rifts', 'drone', 'None: an unmanned drone, flown by its computer or by a remote operator.', 'None; no pilot or passenger compartment.', 'Cannot drive on the ground.', 'Hovers, VTOL, and flies at up to 140 mph (224 km), cruising at 60-100 mph (96-160 km); ceiling 13,000 ft (3,962 m). Speed and altitude halve with a load over 15 tons, and weather or an awkward load may slow it more. Range unlimited, but the rotors need a two hour cool-down after 48 hours of continuous use.', NULL, 'Height 20 ft (6.1 m); width 50 ft (15.2 m); length 60 ft (18.3 m). The robot arm reaches 24 ft (7.3 m)', '15 tons empty', 450, 1, NULL, 18000000, '21 million credits nuclear (about 15 year life), 18 million Solid Oxide; replacement smoke missiles extra. Fair availability, best at Ishpeming and MercTown; seldom sold to individuals or small groups unless they are famous heroes, a big known mercenary company, an army, a nation or a business.', 'Model NG BRV-10 (Class: Unmanned Aerial Battlefield Recovery Vehicle), from lead designers Marc Ferrari, Robb Dunn, Jonathan E. Conroy, J.A. Burke and Walton Harcles. In effect a flying robot: NG used it in-house for almost seven years before selling it openly in spring 107 P.A. It suits armies, city-states, big mercenary companies and large manufacturers and freight haulers (the Black Market included) more than adventurers, and flocks of them shuttle freight between factories, warehouses, docks and showrooms across Ishpeming and the Manistique Imperium. It could fly thousands of miles but most trips are under 100 miles (160 km), typically short hops between a base and the front. It is unmanned so that the space goes to armour, rotors and thrusters and so no crew is risked in hot zones. Three big shrouded, pivoting rotors give lift, agility in tight spaces, VTOL and fairly quiet flight under smoke or darkness; the V-tail has small steering thrusters and two rear thrusters for forward push. It is built to lift, not to race. Cargo: 40 tons slung by cables or a cargo net released on landing, 15 tons in the robot arm, or a wheeled container or hover platform of up to 55 tons towed at no more than 50 mph (80 km), which is risky and not advised. Cables need a ground crew or an escort of 2-3 power armor to hook up. The centreline claw arm (P.S. 60, never used to fight) is what sets it apart: it digs through debris for survivors, plucks the reinforced pilot compartment out of a robot whose Main Body is gone, lifts downed pilots, trapped power armor, soldiers, a trailer of wounded or a single Med-Box, carries off unexploded ordnance, wreckage, salvage, monster carcasses, generators and pallets, carries ground troops on a cable-slung platform, clears roads and battlefields of wrecks, trees and rockfalls, and places posts, pillars, fencing, wire and machinery exactly where a camp is being built. The Black Market and the raiders and mercs it resells to use stolen ones to strip battlefields as soon as the shooting stops, grabbing the best gear and leaving the wounded, and fly off when fired on; a few have snatched unguarded cargo from docks, yards and even military bases. Sensors: as robot vehicles, but no life support, crew space or combat computer; the radar, communications and other sensors fill what would be the cockpit. Communications: 50 mile (80 km) range, radio and video, sharing data and live feed with several authorized users at once. Twenty hidden cameras on the wings, nose, tail and belly serve the remote operator. A nose multi-optics turret turns 360 degrees and looks up 30 degrees and down and back 180, but never straight up; it has passive nightvision, infrared (sees through smoke, but its beam can be seen by infrared viewers) and ultraviolet to 2,000 ft (610 m), a 12x telescopic camera to 2.5 miles (4 km), and a 50 mile (80 km) live video feed that records 2,400 hours of video and 80,000 stills. Eight belly lights help ground crews and the operator. Control: 50 mile (80 km) range. It flies to preset coordinates (changeable in flight), takes evasive action if attacked and reports incoming aircraft, flyers and missiles. Its computer lands and takes off at 95%, or the operator does it by video and instruments; a failure is a hard landing (drone and cargo take 5D6 M.D.) or a slow, wobbly take-off. The operator can fly it by video for short recovery and rescue work, and it can home on a cockpit rescue beacon or any chosen beacon to find pick-up and drop points. Light loads are scooped up by the arm; heavy ones are cabled on while it hovers and waits for the ground crew''s signal. It has no artificial intelligence. NG''s Drone Control and Command Gauntlet (described under Fido) can run it. Damage: losing one rotor or the tail halves speed and altitude and gives -2 to dodge; losing two rotors, or a rotor and the tail, brings it down and the cargo falls. Roll 1D20: on 1-15 both crash, main body and cargo each taking 1D4x100 M.D.C., and the drone is probably destroyed and the cargo lost if not ruined (G.M.''s call); on 16-20 it drops the cargo (2D6x10 M.D.C. to the cargo) and crash-lands for 1D6x10 M.D.C., salvageable if recovered. Losing one rear thruster cuts speed 10%, both 20%. Power: Solid Oxide or nuclear only.', 'Rifts World Book 34: Northern Gun Two p.241-243');

