INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-dx202-cargo-walker', 1, 'Forklift Hand to Hand Combat', 'Swat or jab 1D6 M.D.; punch 3D6 M.D.; power punch 1D4x10 M.D. (counts as two attacks); grab and crush between the forks 1D6 M.D.; stomp 1D4 M.D. against targets 4 ft (1.2 m) tall or smaller', 1, 'Melee', 'One attack per melee plus the pilot''s; four in all under remote control', NULL, NULL, 'It has no weapon systems besides what the pilot carries; damage is low because it was not built to fight. NG''s Combat Kit (a gear row) converts it.'),
  ('ng-dx204-grub', 1, 'Palm Lasers (8 per hand)', 'Four settings: 4D6 S.D.C., 1D6x10 S.D.C., 1D4 M.D. or 2D4 M.D. per laser; multiply for several fired at one target, up to 1D6x10 M.D. from all eight in one palm', 1, '100 ft (30.5 m)', NULL, 'Unlimited', NULL, 'Cutting and welding tools of limited range and power. The two hands cannot fire linked.'),
  ('ng-dx204-grub', 2, 'Main Arm Hand to Hand Combat', 'Swat or jab 1D6 M.D.; punch 3D6 M.D.; power punch 1D6x10 M.D. (counts as two attacks); grab and crush between the fingers 1D6 M.D.; stomp 1D4 M.D. against targets 4 ft (1.2 m) tall or smaller', 1, 'Melee', 'One attack per melee plus the pilot''s; four in all under remote control', NULL, NULL, 'It has no weapons besides the palm lasers and what the pilot carries.'),
  ('ng-brv10-vulture', 1, 'NG-SM16 Mini-Missile Wing Tube Launchers (2 per wing)', 'Smoke mini-missiles none; high-explosive mini-missiles 1D4x10 M.D.', 1, 'One mile (1.6 km)', 'Singly or in volleys of 2 or 4; a volley of any size is one melee attack', '16 mini-missiles, four in each of the four launchers: eight smoke and eight high-explosive', 'None: it is not a combat machine and has no targeting bonuses', 'Smoke screens its landings, take-offs and work in hot zones (its infrared optics see through it); the explosive missiles shoot down missiles and volleys fired at it. Primary purpose: cover with smoke. Secondary: anti-missile defense.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 machines are in' AS assertion, count(*) AS got, 5 AS want
  FROM vehicles WHERE slug IN ('ng-mau-500-coffin', 'ng-robot-floater-camera', 'ng-dx202-cargo-walker', 'ng-dx204-grub', 'ng-brv10-vulture');
SELECT 'their 41 locations are in' AS assertion, count(*) AS got, 41 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-mau-500-coffin', 'ng-robot-floater-camera', 'ng-dx202-cargo-walker', 'ng-dx204-grub', 'ng-brv10-vulture');
SELECT 'their 4 weapon entries are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-mau-500-coffin', 'ng-robot-floater-camera', 'ng-dx202-cargo-walker', 'ng-dx204-grub', 'ng-brv10-vulture');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-mau-500-coffin', 'ng-robot-floater-camera', 'ng-dx202-cargo-walker', 'ng-dx204-grub', 'ng-brv10-vulture') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

